  static String get(String key) {
    switch (key.toLowerCase()) {
      case 'crate':
        return crate;
      case 'toolkit':
        return toolkit;
      case 'cupboard':
        return cupboard;
      case 'orcus':
      case 'logo':
        return orcusLogo;
      case 'armoury':
      default:
        return armoury;
    }
